<?php use App\Support; $pages = max(1, (int)ceil($total / $perPage)); ?>
<div class="page-head"><div><span class="eyebrow">QUẢN LÝ ĐƠN</span><h1>Đơn hàng</h1><p><?= number_format($total) ?> đơn đang được lưu trong tài khoản của bạn.</p></div><form method="post" action="/sync"><input type="hidden" name="_csrf" value="<?= Support::csrfToken() ?>"><input type="hidden" name="scope" value="all"><button class="btn primary">Kiểm tra đơn mới</button></form></div>
<form class="filter-bar" method="get"><input name="q" value="<?= Support::e($search) ?>" placeholder="Tìm theo mã đơn, tên khách hoặc sản phẩm..."><select name="status"><option value="">Tất cả trạng thái</option><?php foreach (['received','mapping_required','ready','submitting','running','completed','cancelled','retry_waiting','manual_review','failed'] as $s): ?><option value="<?= $s ?>" <?= $status === $s ? 'selected' : '' ?>><?= Support::e(Support::statusLabel($s)) ?></option><?php endforeach; ?></select><button class="btn secondary">Tìm kiếm</button></form>
<section class="panel"><div class="table-wrap"><table class="orders-table"><thead><tr><th>Mã đơn</th><th>Sản phẩm</th><th>Khách hàng</th><th>Giá trị</th><th>Trạng thái</th><th>Cập nhật</th></tr></thead><tbody><?php foreach ($orders as $row): ?><tr><td><a href="/order?id=<?= (int)$row['id'] ?>"><b>#<?= (int)$row['nas_order_id'] ?></b></a><small>Gian hàng <?= (int)$row['nas_bot_id'] ?></small></td><td><b><?= Support::e($row['nas_product_name']) ?></b><small>Mã sản phẩm <?= (int)$row['nas_product_id'] ?></small></td><td><?= Support::e($row['customer_username'] ? '@'.$row['customer_username'] : trim($row['customer_first_name'].' '.$row['customer_last_name'])) ?><small><?= Support::e($row['customer_telegram_id']) ?></small></td><td><?= number_format((float)$row['total_amount']) ?>đ</td><td><span class="badge <?= Support::badgeClass($row['processing_status']) ?>"><?= Support::e(Support::statusLabel($row['processing_status'])) ?></span><?php if ($row['notification_sent'] === 0 || $row['notification_sent'] === '0'): ?><small class="danger-text">Chưa báo được cho khách</small><?php endif; ?></td><td><?= Support::e($row['updated_at'] ?: $row['created_at']) ?></td></tr><?php endforeach; ?><?php if (!$orders): ?><tr><td colspan="6" class="empty">Không tìm thấy đơn phù hợp.</td></tr><?php endif; ?></tbody></table></div></section>
<?php if ($pages > 1): ?><nav class="pagination"><?php for ($i=1; $i <= $pages; $i++): ?><a class="<?= $i === $page ? 'active' : '' ?>" href="?page=<?= $i ?>&status=<?= urlencode($status) ?>&q=<?= urlencode($search) ?>"><?= $i ?></a><?php endfor; ?></nav><?php endif; ?>
